begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/phase-9-salon.inc
update public.salon_memberships set role_code='reception',location_id='a4000000-0000-4000-8000-000000000011' where id='a4000000-0000-4000-8000-000000000111';
insert into public.locations(id,organization_id,name,timezone) values('a4000000-0000-4000-8000-000000000013','a4000000-0000-4000-8000-000000000001','Other location','Europe/Istanbul');
set local role authenticated;
insert into salon_results values('readiness',public.appointment_readiness('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','a4000000-0000-4000-8000-000000000301'));
select is((select value#>>'{data,preparation_status}' from salon_results where name='readiness'),'CONSULTATION_REQUIRED','reception receives authoritative preparation status');
select is((select value#>>'{data,technical_clearance}' from salon_results where name='readiness'),'false','projection cannot authorize chemicals');
select is((select value#>>'{data,strand_test_status}' from salon_results where name='readiness'),'UNKNOWN','unknown strand test requirement is not fabricated');
select is((select array_agg(k order by k) from salon_results,jsonb_object_keys(value->'data') k where name='readiness'),array['allocated_minutes','appointment_id','appointment_version','consultation_required','duration_source','evaluated_at','preparation_status','schema_version','strand_test_status','technical_clearance'],'exact minimal keys, no technical payload');
select is(public.appointment_readiness('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000013','a4000000-0000-4000-8000-000000000301')->>'code','TENANT_CONTEXT_INVALID','same org other location denied');
select is(public.appointment_readiness('a4000000-0000-4000-8000-000000000112','a4000000-0000-4000-8000-000000000012','a4000000-0000-4000-8000-000000000301')->>'code','TENANT_CONTEXT_INVALID','forged membership and foreign organization denied');
select is(public.appointment_readiness('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011',gen_random_uuid())->>'code','SALON_NOT_FOUND','unrelated appointment existence not disclosed');
reset role;
update public.salon_memberships set status='revoked',revoked_at=now() where id='a4000000-0000-4000-8000-000000000111';
set local role authenticated;
select is(public.appointment_readiness('a4000000-0000-4000-8000-000000000111','a4000000-0000-4000-8000-000000000011','a4000000-0000-4000-8000-000000000301')->>'code','MEMBERSHIP_REVOKED','revocation denies projection');
reset role;
\ir fixtures/gate-1-live.inc
select is((select count(*) from public.live_sessions),1::bigint,'technical fixture really contains a full session');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000024',true);
set local role authenticated;
select is((select count(*) from public.live_sessions),0::bigint,'reception full live payload is hidden by RLS');
select is((select count(*) from public.live_session_versions),0::bigint,'versions do not leak full payload');
select is((select count(*) from public.hair_passports),0::bigint,'reception full passport is hidden');
select is((select count(*) from public.hair_observations),0::bigint,'reception observations hidden');
select is((select count(*) from public.hair_evidence),0::bigint,'reception evidence hidden');
select is(public.hair_passport_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000031','{}',gen_random_uuid())->>'code','FORBIDDEN','direct legacy Hair RPC also denied');
select is((select count(*) from storage.objects where bucket_id='live-technical'),0::bigint,'reception cannot download reserved private technical photos');
select ok(not app_private.user_has_permission('b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000011','cost.view'),'reception acquisition cost denied');
select ok(not app_private.user_has_permission('b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000011','commission.view_all'),'reception team commission denied');
select is(public.crm_read('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"operation":"summary","client_id":"b4000000-0000-4000-8000-000000000031"}')#>>'{data,summary,last_technical_memory}',null,'CRM operational summary does not re-leak technical memory');
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"kind":"TECHNICAL","period":"THIS_MONTH"}',gen_random_uuid())->>'code','FORBIDDEN','technical report denied');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
set local role authenticated;
select is((select count(*) from public.live_sessions),1::bigint,'authorized manager/owner still reads technical session');
select * from finish();rollback;
